/** verifyVectors: re-run every vector and compare with the pinned result. */
export function verifyVectors(): { setId: string; total: number; passed: number; failures: { id: string; detail: string }[] } {
  // The failures.
  const failures: { id: string; detail: string }[] = [];
  // Each vector.
  for (const v of VECTORS) {
    // The engine's answer today.
    const got = JSON.stringify(run(v.input));
    // The pinned answer.
    const want = JSON.stringify(v.expect);
    // Compare.
    if (got !== want) failures.push({ id: v.id, detail: "result differs from the pinned value" });
  }
  // Report.
  return { setId: GOLDEN_VECTOR_SET_ID, total: VECTORS.length, passed: VECTORS.length - failures.length, failures };
}
